import './workspace-ux.js';
import {uiIcon} from './ui-icons.js';
import './manual-arrows.js';
import {navigationPage} from './navigation.js';
import './i18n.js';
import {addUpdates} from './updates-ui.js';
import {getSettings,saveSettings,avatarSVG,escapeHTML as esc} from './settings.js';
const option=(value,label,current)=>`<option value="${value}" ${value===current?'selected':''}>${label}</option>`;
const select=(key,label,items,s)=>`<label>${label}<select data-setting="${key}">${items.map(([v,l])=>option(v,l,s[key])).join('')}</select></label>`;
const dialog=document.createElement('dialog');dialog.id='preferences';document.body.append(dialog);
const settingsStyle=document.createElement('link');settingsStyle.rel='stylesheet';settingsStyle.href=new URL('./preferences.css',import.meta.url).href;document.head.append(settingsStyle);
const switches=(keys,s)=>`<div class="preference-switches">${keys.map(([key,label])=>`<label class="preference-switch"><span>${label}</span><input type="checkbox" role="switch" data-setting="${key}" ${s[key]?'checked':''}><span class="switch-track" aria-hidden="true"></span></label>`).join('')}</div>`;
let settingsSection='appearance';
function selectSettingsSection(name){settingsSection=name;dialog.querySelectorAll('[data-settings-section]').forEach(p=>p.hidden=p.dataset.settingsSection!==name);dialog.querySelectorAll('[data-settings-nav]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.settingsNav===name)));dialog.querySelector('.preferences-content').scrollTop=0}
export function renderSettings(){const s=getSettings();dialog.setAttribute('aria-labelledby','preferencesTitle');dialog.innerHTML=`
<div class="preferences-header"><div><h2 id="preferencesTitle">Impostazioni</h2></div><button class="dialog-close" aria-label="Chiudi impostazioni" id="closePreferences">×</button></div>
<div class="preferences-layout"><nav class="preferences-nav" aria-label="Sezioni delle impostazioni"><button data-settings-nav="appearance" aria-pressed="true"><span aria-hidden="true">◐</span>Aspetto</button><button data-settings-nav="game" aria-pressed="false"><span aria-hidden="true">♟</span>Partita</button><button data-settings-nav="coach" aria-pressed="false"><span aria-hidden="true">☺</span>Il tuo coach</button>${window.plystreakDesktop?'<button data-settings-nav="app" aria-pressed="false"><span aria-hidden="true">↻</span>App per PC</button>':''}</nav>
<div class="preferences-content">
<section data-settings-section="appearance"><h3>Lingua e aspetto</h3><p class="section-description">Scegli la lingua e l’aspetto della scacchiera.</p><div class="settings-grid">${select('language','Lingua',[['it','Italiano'],['en','English'],['es','Español'],['fr','Français'],['de','Deutsch']],s)}${select('theme','Aspetto',[['system','Automatico · sistema'],['light','Chiaro'],['dark','Scuro']],s)}${select('board','Scacchiera',[['amethyst','Ametista'],['lavender','Lavanda'],['green','Verde classico'],['walnut','Noce'],['slate','Ardesia']],s)}${select('animation','Movimento dei pezzi',[['normal','Fluido'],['slow','Lento'],['off','Disattivato']],s)}</div><details class="translation-note"><summary>Informazioni sulle traduzioni</summary><p>Traduzioni di interfaccia e coach. Alcune note del catalogo e informazioni tecniche sono ancora in italiano.</p></details></section>
<section data-settings-section="game" hidden><h3>Aiuti e suoni</h3><p class="section-description">Regola gli aiuti visivi e il suono durante la partita.</p>${switches([['coordinates','Coordinate sulla scacchiera'],['legal','Mostra mosse legali'],['sound','Suono delle mosse']],s)}</section>
<section data-settings-section="coach" hidden><div class="coach-settings-preview"><div id="avatarPreview">${avatarSVG(s)}</div><div><span class="eyebrow">IL TUO ISTRUTTORE</span><h3 id="settingsCoachName" translate="no">${esc(s.coachName)}</h3><p>Un compagno illustrato, con lo stile che scegli tu.</p></div></div><label class="name-field">Nome del coach<input data-setting="coachName" maxlength="18" value="${esc(s.coachName)}"></label><div class="settings-grid">${select('avatarShape','Forma',[['round','Morbida'],['square','Robot'],['cat','Gatto']],s)}${select('avatarColor','Colore',[['sage','Salvia'],['sky','Cielo'],['plum','Lilla'],['sun','Miele']],s)}${select('avatarEyes','Espressione',[['friendly','Curioso'],['focused','Concentrato'],['happy','Sorridente']],s)}${select('avatarAccessory','Accessorio',[['none','Nessuno'],['glasses','Occhiali'],['crown','Corona'],['headphones','Cuffie']],s)}</div><h4 class="settings-subheading">Come ti accompagna</h4><div class="settings-grid">${select('coachTone','Tono del coach',[['warm','Incoraggiante'],['direct','Diretto'],['quiet','Essenziale']],s)}${select('coachFrequency','Quando commentare',[['all','Ogni mia mossa'],['errors','Solo mosse da rivedere']],s)}</div>${switches([['coachHints','Consenti indizi strategici su richiesta']],s)}</section>
<section data-settings-section="app" hidden id="settingsUpdates"></section>
</div></div><div class="preferences-footer"><p id="settingsStatus" role="status">Preferenze salvate su questo dispositivo.</p><button id="resetSettings" class="text-button">Ripristina le impostazioni</button><button id="donePreferences" class="primary">Fatto</button></div>`;
addUpdates(dialog.querySelector('#settingsUpdates'));
selectSettingsSection(settingsSection==='app'&&!window.plystreakDesktop?'appearance':settingsSection);
dialog.querySelectorAll('[data-settings-nav]').forEach(b=>b.onclick=()=>selectSettingsSection(b.dataset.settingsNav));
dialog.querySelector('#closePreferences').onclick=dialog.querySelector('#donePreferences').onclick=()=>dialog.close();
dialog.onchange=e=>{const key=e.target.dataset.setting;if(!key)return;const saved=saveSettings({[key]:e.target.type==='checkbox'?e.target.checked:e.target.value,...(key.startsWith('avatar')||key.startsWith('coach')?{coachPreset:'custom'}:{})});dialog.querySelector('#avatarPreview').innerHTML=avatarSVG();dialog.querySelector('#settingsCoachName').textContent=getSettings().coachName;dialog.querySelector('#settingsStatus').textContent=saved?'Preferenze salvate su questo dispositivo.':'Memoria non disponibile: impostazioni attive solo in questa sessione.'};
dialog.querySelector('#resetSettings').onclick=async()=>{const {defaults}=await import('./settings.js');saveSettings(defaults);renderSettings();dialog.querySelector('#resetSettings').focus()}}
export function openSettings(){renderSettings();dialog.showModal()}
const header=document.querySelector('header');const nav=document.createElement('nav');nav.className='app-nav';nav.setAttribute('aria-label','Menu principale');const page=navigationPage(location.pathname);nav.innerHTML=[['live.html','Dal vivo'],['coach.html','Gioca'],['index.html','Analizza'],['progress.html','Progressi'],['practice.html','Esercizi'],['openings.html','Aperture']].map(([url,label])=>`<a href="${url}" ${page===url?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${uiIcon(({'live.html':'live','coach.html':'coach','index.html':'analysis','progress.html':'progress','practice.html':'practice','openings.html':'openings'})[url])}</span><span>${label}</span></a>`).join('')+`<button id="preferencesButton" aria-label="Impostazioni e avatar"><span class="nav-icon" aria-hidden="true">${uiIcon('settings')}</span><span class="settings-label-full">Impostazioni</span><span class="settings-label-short">Opzioni</span></button>`;header.append(nav);document.querySelector('#preferencesButton').onclick=openSettings;document.querySelectorAll('[data-open-settings]').forEach(b=>b.onclick=openSettings);

window.plystreakDesktop?.healthy().catch(()=>{});

// The mascot replaces the existing brand glyph without adding a floating overlay.
const brand=document.querySelector('.brand');
if(brand){
 const icon=document.createElement('img');icon.src=new URL('./mascot-ply.svg',import.meta.url).href;icon.alt='';icon.setAttribute('aria-hidden','true');icon.width=42;icon.height=42;icon.className='ply-mascot';
 const old=brand.querySelector('.brand-icon');if(old)old.replaceWith(icon);else{for(const node of brand.childNodes)if(node.nodeType===Node.TEXT_NODE)node.textContent=node.textContent.replace('♘','');brand.prepend(icon)}
}

const installLink=document.createElement("a");installLink.href="install.html";installLink.textContent="Installa Plystreak e prepara l’uso offline";installLink.className="text-button";document.querySelector("main")?.append(installLink);
